/**
 * Converts numbers into Indian Currency words (Rupees and Paise)
 * e.g. 10710 -> "Rupees Ten Thousand Seven Hundred and Ten Only."
 * e.g. 5876.01 -> "Rupees Five Thousand Eight Hundred and Seventy-Six and One Paise Only."
 */
export function numberToWordsINR(amount: number): string {
  if (isNaN(amount) || amount === 0) return 'Rupees Zero Only.';

  const a = [
    '', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine',
    'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'
  ];
  const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];

  function convertGroup(n: number): string {
    if (n === 0) return '';
    if (n < 20) return a[n];
    if (n < 100) return b[Math.floor(n / 10)] + (n % 10 !== 0 ? '-' + a[n % 10] : '');
    if (n < 1000) return a[Math.floor(n / 100)] + ' Hundred' + (n % 100 !== 0 ? ' and ' + convertGroup(n % 100) : '');
    if (n < 100000) return convertGroup(Math.floor(n / 1000)) + ' Thousand' + (n % 1000 !== 0 ? ' ' + convertGroup(n % 1000) : '');
    if (n < 10000000) return convertGroup(Math.floor(n / 100000)) + ' Lakh' + (n % 100000 !== 0 ? ' ' + convertGroup(n % 100000) : '');
    return convertGroup(Math.floor(n / 10000000)) + ' Crore' + (n % 10000000 !== 0 ? ' ' + convertGroup(n % 10000000) : '');
  }

  const rounded = Math.round(amount * 100) / 100;
  const integerPart = Math.floor(rounded);
  const decimalPart = Math.round((rounded - integerPart) * 100);

  let words = 'Rupees ' + convertGroup(integerPart).trim();
  if (decimalPart > 0) {
    words += ' and ' + convertGroup(decimalPart).trim() + ' Paise';
  }
  words += ' Only.';
  return words;
}

/**
 * Format date to official ordinal format: "16th November 2026"
 */
export function formatOrdinalDate(dateInput: Date | string | number): string {
  const date = new Date(dateInput);
  if (isNaN(date.getTime())) return '';
  const day = date.getDate();
  const j = day % 10;
  const k = day % 100;
  let suffix = 'th';
  if (j === 1 && k !== 11) suffix = 'st';
  else if (j === 2 && k !== 12) suffix = 'nd';
  else if (j === 3 && k !== 13) suffix = 'rd';

  const months = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ];
  return `${day}${suffix} ${months[date.getMonth()]} ${date.getFullYear()}`;
}

/**
 * Format pickup time range: "Between 5:00 AM and 5:30 AM"
 */
export function formatPickupTimeRange(dateInput: Date | string | number): string {
  const date = new Date(dateInput);
  if (isNaN(date.getTime())) return '5:00 AM';

  const hours = date.getHours();
  const minutes = date.getMinutes();
  const ampm = hours >= 12 ? 'PM' : 'AM';
  const h12 = hours % 12 || 12;
  const mStr = minutes < 10 ? `0${minutes}` : `${minutes}`;

  // 30 min window
  const endDate = new Date(date.getTime() + 30 * 60 * 1000);
  const endHours = endDate.getHours();
  const endMinutes = endDate.getMinutes();
  const endAmpm = endHours >= 12 ? 'PM' : 'AM';
  const endH12 = endHours % 12 || 12;
  const endMStr = endMinutes < 10 ? `0${endMinutes}` : `${endMinutes}`;

  return `Between ${h12}:${mStr} ${ampm} and ${endH12}:${endMStr} ${endAmpm}`;
}

/**
 * Extract clean city / area name from address string
 */
function extractCityOrArea(address?: string | null): string {
  if (!address) return '';
  const parts = address.split(',').map((p) => p.trim()).filter(Boolean);
  if (parts.length === 0) return '';

  for (let i = parts.length - 1; i >= 0; i--) {
    const part = parts[i];
    if (/bengaluru|bangalore|mangaluru|mangalore|mysuru|mysore|udupi|manipal|coorg|madikeri|goa|hubballi|belagavi|bantwal|puttur|hassan|chikmagalur|kasaragod|kannur/i.test(part)) {
      return part.replace(/\s*–.*$/, '').trim();
    }
  }
  return parts.length > 2 ? parts[parts.length - 2] : parts[0];
}

/**
 * Format Trip Route e.g. "Bengaluru – Bantwal – Bengaluru"
 */
export function formatInvoiceRoute(
  pickupAddress?: string | null,
  dropAddress?: string | null,
  tripType?: string,
  extra?: { viaStops?: any[]; airportDirection?: string; localHours?: number; distanceKm?: number }
): string {
  const origin = extractCityOrArea(pickupAddress) || 'Bengaluru';
  const destination = extractCityOrArea(dropAddress) || 'Mangaluru';
  const typeKey = (tripType || 'ONEWAY').toUpperCase();

  // 1. Local / Hourly Rental
  if (typeKey.includes('LOCAL') || typeKey.includes('PACKAGE') || typeKey.includes('HOURLY')) {
    const hours = extra?.localHours || 8;
    const km = extra?.distanceKm || 80;
    return `${origin} City / Local Rental (${hours} Hrs / ${km} Km)`;
  }

  // 2. Airport Transfer
  if (typeKey.includes('AIRPORT')) {
    const isAirportDrop = extra?.airportDirection === 'DROP' || /airport|ixe|blr|kempegowda/i.test(destination);
    const isAirportPickup = extra?.airportDirection === 'PICKUP' || /airport|ixe|blr|kempegowda/i.test(origin);
    if (isAirportDrop) {
      return `${origin} → Airport Drop (${destination})`;
    }
    if (isAirportPickup) {
      return `Airport Pickup (${origin}) → ${destination}`;
    }
    return `${origin} → ${destination} (Airport Transfer)`;
  }

  // 3. Corporate Travel
  if (typeKey.includes('CORP')) {
    return `${origin} ↔ ${destination} (Corporate Commute)`;
  }

  // 4. Round Trip
  const isRoundTrip = typeKey === 'ROUND_TRIP' || typeKey === 'ROUND' || typeKey.includes('ROUND');
  if (isRoundTrip) {
    if (origin.toLowerCase() === destination.toLowerCase()) {
      return `${origin} – City Tour – ${origin}`;
    }
    return `${origin} ↔ ${destination} ↔ ${origin}`;
  }

  // 5. One Way with Via Stops
  const viaList = extra?.viaStops || [];
  if (viaList.length > 0) {
    const viaNames = viaList
      .map((s: any) => typeof s === 'string' ? extractCityOrArea(s) : extractCityOrArea(s?.label || s?.address || ''))
      .filter(Boolean);
    if (viaNames.length > 0) {
      return `${origin} → Via (${viaNames.join(', ')}) → ${destination}`;
    }
  }

  // 6. Standard One Way
  return `${origin} → ${destination}`;
}

/**
 * Human-readable trip type label
 */
export function formatTripTypeLabel(
  tripType?: string,
  extra?: { durationDays?: number; localHours?: number; distanceKm?: number; flightNumber?: string; corporateMode?: string; corporateTotalDays?: string; viaCount?: number }
): string {
  const typeKey = (tripType || 'ONEWAY').toUpperCase();

  if (typeKey === 'ROUND' || typeKey === 'ROUND_TRIP' || typeKey.includes('ROUND')) {
    const days = extra?.durationDays || 1;
    return days > 1 ? `Round Trip Outstation (${days} Days)` : '1 Day Round Trip (Same-Day Return)';
  }

  if (typeKey === 'LOCAL' || typeKey === 'PACKAGE' || typeKey === 'HOURLY_RENTAL' || typeKey.includes('LOCAL')) {
    const hours = extra?.localHours || 8;
    const km = extra?.distanceKm || 80;
    return `Local Rental Package (${hours} Hrs / ${km} Km)`;
  }

  if (typeKey === 'AIRPORT' || typeKey.includes('AIRPORT')) {
    return extra?.flightNumber ? `Airport Transfer (Flight: ${extra.flightNumber})` : 'Airport Transfer Service';
  }

  if (typeKey === 'CORPORATE' || typeKey.includes('CORP')) {
    return extra?.corporateMode === 'DAILY'
      ? `Corporate Daily Commute (${extra?.corporateTotalDays || 'Multiple'} Days)`
      : 'Corporate Executive Travel';
  }

  if (typeKey === 'ONEWAY' || typeKey === 'ONE_WAY' || typeKey.includes('ONE')) {
    const count = extra?.viaCount || 0;
    return count > 0 ? `One Way Multi-Stop Drop (${count} Via)` : 'One Way Drop (Outstation)';
  }

  return tripType ? tripType.replace(/_/g, ' ') : 'Outstation Trip';
}

/**
 * Build standard KandyInvoiceData from Prisma Booking record
 */
export function buildKandyInvoiceData(booking: any): KandyInvoiceData {
  const estimatedFare = Number(booking.estimatedFare || 0);
  const advanceAmount = Number(booking.advanceAmount || 0);
  const balanceAmount = Number(booking.balanceAmount || 0);
  const tollAmount = Number(booking.tollAmount || 0);
  const parkingAmount = Number(booking.parkingAmount || 0);
  const driverAllowance = Number(booking.driverAllowance || 0);

  // Grand total including toll/parking if charged
  const totalWithExtras = estimatedFare + tollAmount + parkingAmount;

  // Reverse calculate 5% GST (Taxable Value + 2.5% CGST + 2.5% SGST)
  const taxableValue = Math.round((estimatedFare / 1.05) * 100) / 100;
  const gstTotal = Math.round((estimatedFare - taxableValue) * 100) / 100;
  const cgst = Math.round((gstTotal / 2) * 100) / 100;
  const sgst = Math.round((gstTotal - cgst) * 100) / 100;

  // Base service fare (taxable minus chauffeur allowance)
  const serviceAmount = Math.max(0, Math.round((taxableValue - driverAllowance) * 100) / 100);

  // Extract booking created event payload if available
  const createdEvent = booking.tripEvents?.find((e: any) => e.type === 'BOOKING_CREATED');
  const payload = (createdEvent?.payloadJson as any) || {};

  const distanceKm = Math.round(Number(booking.distanceKm || booking.actualDistanceKm || payload.distanceKm || 100));

  // Extract trip parameters
  const tripTypeKey = String(booking.tripType || payload.tripType || 'ONEWAY').toUpperCase();
  const viaStopsList: any[] = Array.isArray(payload.viaStops) ? payload.viaStops : (Array.isArray(payload.stops) ? payload.stops : []);
  const localHours = Number(payload.localHours || payload.packageHours || (tripTypeKey.includes('LOCAL') ? 8 : 0));
  const flightNumber = payload.flightNumber || '';
  const airportDirection = payload.airportDirection || '';
  const durationDays = Number(payload.durationDays || (tripTypeKey.includes('ROUND') ? 1 : 1));
  const corporateMode = payload.corporateMode || '';
  const corporateTotalDays = payload.corporateTotalDays || '';

  const extraMeta = {
    viaStops: viaStopsList,
    viaCount: viaStopsList.length,
    localHours,
    distanceKm,
    flightNumber,
    airportDirection,
    durationDays,
    corporateMode,
    corporateTotalDays,
  };

  const tripTypeFormatted = formatTripTypeLabel(booking.tripType || payload.tripType, extraMeta);
  const routeStr = formatInvoiceRoute(booking.pickupAddress, booking.dropAddress, booking.tripType || payload.tripType, extraMeta);

  // KM Limit description according to trip type
  let kmLimitStr = `${distanceKm} Kilometres Limit`;
  if (tripTypeKey.includes('LOCAL') || tripTypeKey.includes('PACKAGE')) {
    kmLimitStr = `${distanceKm} Km Limit (${localHours || 8} Hrs Package)`;
  } else if (tripTypeKey.includes('ROUND')) {
    kmLimitStr = `${distanceKm} Km Total (${durationDays} Day${durationDays > 1 ? 's' : ''} Allowance)`;
  }

  // Vehicle information
  const vehicleCategory = payload.category || booking.vehicle?.model || booking.vehicle?.category || '';
  const vehicleName = booking.vehicle
    ? `${booking.vehicle.make || ''} ${booking.vehicle.model || ''}`.trim() || booking.vehicle.registrationNumber || vehicleCategory
    : vehicleCategory ? vehicleCategory.replace(/_/g, ' ') : 'Commercial AC Cab';

  // Passengers formatting
  const passengerCount = Number(payload.passengers || payload.passengerCount) || (booking.vehicle?.seatCount ? booking.vehicle.seatCount - 1 : 4);
  const luggageStr = payload.luggage ? ` • ${payload.luggage}` : '';
  const passengersStr = `${passengerCount} Passenger${passengerCount > 1 ? 's' : ''}${luggageStr}`;

  // Service description according to trip type
  let serviceDescription = `${tripTypeFormatted} - ${distanceKm} Km Limit (${vehicleName})`;
  if (tripTypeKey.includes('ROUND')) {
    serviceDescription = `Outstation Round Trip (${durationDays} Day${durationDays > 1 ? 's' : ''} - ${distanceKm} Km Limit) - ${vehicleName}`;
  } else if (tripTypeKey.includes('LOCAL') || tripTypeKey.includes('PACKAGE')) {
    serviceDescription = `Local City Cab Rental (${localHours || 8} Hrs / ${distanceKm} Km Limit) - ${vehicleName}`;
  } else if (tripTypeKey.includes('AIRPORT')) {
    serviceDescription = `Dedicated Airport Transfer Service (${distanceKm} Km Limit) - ${vehicleName}`;
  } else if (tripTypeKey.includes('CORP')) {
    serviceDescription = `Corporate Dedicated Transportation (${distanceKm} Km Limit) - ${vehicleName}`;
  }

  // Remarks according to trip type
  let remarks = `Toll and parking charges, additional kilometres beyond the ${distanceKm} Km limit, and applicable chauffeur night allowance are not included in this invoice amount and will be charged extra as applicable.`;
  if (tripTypeKey.includes('LOCAL') || tripTypeKey.includes('PACKAGE')) {
    remarks = `Toll charges, parking fees, additional hours beyond ${localHours || 8} hours, and extra kilometres beyond ${distanceKm} Km package limit are charged extra as per standard tariff.`;
  } else if (tripTypeKey.includes('ROUND')) {
    remarks = `Toll charges, state border permits, parking fees, additional kilometres beyond ${distanceKm} Km limit, and chauffeur night allowance are charged extra as applicable.`;
  } else if (tripTypeKey.includes('AIRPORT')) {
    remarks = `Airport entry/parking fees and toll charges are charged extra as per actual receipts. Safe luggage assistance included.`;
  } else if (tripTypeKey.includes('CORP')) {
    remarks = `Corporate travel invoice under contracted corporate billing. Toll and parking receipts appended separately.`;
  }

  // Invoice Number Formatting (Enforce KC-2026-XXXX format)
  const rawRef = (booking.humanReadableRef || '').trim();
  let invoiceNumber = '';
  if (/^KC-2026-\d+/i.test(rawRef)) {
    invoiceNumber = rawRef.toUpperCase();
  } else if (/^KC-\d+/i.test(rawRef)) {
    // e.g. KC-925966 -> KC-2026-925966
    invoiceNumber = `KC-2026-${rawRef.substring(3)}`;
  } else if (/^\d{4,8}$/.test(rawRef)) {
    // e.g. 925966 -> KC-2026-925966
    invoiceNumber = `KC-2026-${rawRef}`;
  } else if (rawRef.startsWith('INV-')) {
    const stripped = rawRef.replace(/^INV-/, '');
    invoiceNumber = stripped.startsWith('2026-') ? `KC-${stripped}` : `KC-2026-${stripped}`;
  } else if (rawRef) {
    const clean = rawRef.replace(/^KC-?/i, '');
    invoiceNumber = clean.startsWith('2026-') ? `KC-${clean}` : `KC-2026-${clean}`;
  } else {
    invoiceNumber = `KC-2026-${Date.now().toString().slice(-6)}`;
  }

  const scheduledDate = booking.scheduledAt ? new Date(booking.scheduledAt) : new Date(booking.createdAt || Date.now());
  const invoiceDate = booking.createdAt ? new Date(booking.createdAt) : scheduledDate;
  const customerName = booking.customer?.user?.fullName || booking.customerName || 'Customer';

  // Number of days / Duration
  let numberOfDays = '';
  if (tripTypeKey.includes('ROUND')) {
    numberOfDays = durationDays > 1 ? `${durationDays} Days` : '1 Day (Same-Day Return)';
  } else if (tripTypeKey.includes('LOCAL') || tripTypeKey.includes('PACKAGE')) {
    numberOfDays = `${localHours || 8} Hours Package`;
  } else if (tripTypeKey.includes('CORP')) {
    numberOfDays = corporateTotalDays ? `${corporateTotalDays} Days` : '1 Day (Commute)';
  } else {
    numberOfDays = '1 Day (Point-to-Point)';
  }

  // Toll & Parking and additional fares
  let tollParkingStatus = 'Excluded (Payable Extra at Actuals)';
  if (tollAmount > 0 && parkingAmount > 0) {
    tollParkingStatus = `Included (Toll: ₹${tollAmount} + Parking: ₹${parkingAmount})`;
  } else if (tollAmount > 0) {
    tollParkingStatus = `Included (Toll: ₹${tollAmount})`;
  } else if (parkingAmount > 0) {
    tollParkingStatus = `Included (Parking: ₹${parkingAmount})`;
  } else if (payload.tollsIncluded || payload.isTollIncluded) {
    tollParkingStatus = 'Included in Package Fare';
  }

  const chauffeurNightAllowance = Number(payload.nightAllowance || booking.nightAllowance || 0);
  const petFee = Number(payload.petFee || booking.petFee || 0);
  const extraKmAmount = Number(payload.extraKmAmount || booking.extraKmAmount || 0);

  return {
    invoiceNumber,
    invoiceDate: invoiceDate.toISOString(),
    invoiceDateFormatted: formatOrdinalDate(invoiceDate),
    placeOfSupply: 'Karnataka',
    supplyType: 'Passenger Transportation Service',
    bookingRef: invoiceNumber,
    customer: {
      name: customerName.startsWith('Mr.') || customerName.startsWith('Ms.') || customerName.startsWith('Dr.') ? customerName : `Mr. ${customerName}`,
      phone: booking.customer?.user?.phone || booking.customerPhone || '',
      pickupAddress: booking.actualPickupAddress || booking.pickupAddress || 'Address on file',
      email: booking.customer?.email || null,
    },
    tripDetails: {
      travelDate: formatOrdinalDate(scheduledDate),
      tripType: tripTypeFormatted,
      numberOfDays,
      route: routeStr,
      passengers: passengersStr,
      pickupTime: formatPickupTimeRange(scheduledDate),
      kmLimit: kmLimitStr,
      tollParkingStatus,
    },
    financials: {
      serviceDescription,
      serviceAmount: driverAllowance > 0 ? serviceAmount : taxableValue,
      chauffeurAllowance: driverAllowance,
      chauffeurNightAllowance,
      taxableValue,
      cgst,
      sgst,
      gstTotal,
      grandTotal: estimatedFare,
      tollAmount,
      parkingAmount,
      petFee,
      extraKmAmount,
      advancePaid: advanceAmount,
      advanceStatus: booking.advancePaymentStatus || 'COMPLETED',
      balanceDue: balanceAmount + tollAmount + parkingAmount,
      balanceStatus: booking.balancePaymentStatus || 'PENDING',
    },
    amountInWords: numberToWordsINR(estimatedFare),
    remarks,
    company: OFFICIAL_KANDY_COMPANY,
    signatory: OFFICIAL_KANDY_SIGNATORY,
  };
}

